mutations.old:
capped: set = set()
for _ in range(len(names) + 1):
    free = [k for k in names if k not in capped]
    room = sum(raw[k] for k in free)
    remaining = 1.0 - cap * len(capped)
    if not free or room <= 0 or remaining < -1e-12:
        raise PopulationError("ceiling spill has nowhere to go — refusing to drop capital")
    w = {k: cap for k in capped}
    for k in free:
        w[k] = remaining * raw[k] / room
    over = [k for k in free if w[k] > cap + 1e-12]
    if not over:
        return w
    capped |= set(over)

mutations.new:
total = sum(raw.values())
w = {k: raw[k] / total for k in names}
for _ in range(len(names) + 1):
    over = [k for k in names if w[k] > cap + 1e-12]
    if not over:
        return w
    spill = sum(w[k] - cap for k in over)
    for k in over:
        w[k] = cap
    free = [k for k in names if k not in over]
    room = sum(raw[k] for k in free)
    if room <= 0:
        raise PopulationError("ceiling spill has nowhere to go — refusing to drop capital")
    for k in free:
        w[k] += spill * raw[k] / room
